/*! Kuvos physio player v1.10 - dependency free.
 *  Renders an exercise from kuvos-physio-library.json (animation.type = "rig2d_v1").
 *  Usage:
 *    var p = KuvosPhysio.mount(el, exercise, {reps: 10, speed: 1, style: 'human' | 'stick', onFrame: fn});
 *    var tasks = KuvosPhysio.resolvePlan(library, planItemsOrText);
 *  Theme with CSS variables on any ancestor:
 *    --kp-hi (working muscles) --kp-skin --kp-shirt --kp-pants --kp-shoe --kp-hair
 *    --kp-muted (props and stick lines) --kp-line (floor) --kp-tint (props) --kp-bg
 */
(function (root) {
  'use strict';
  var SEG = [[2, 3], [3, 4], [4, 5], [5, 6], [2, 7], [7, 8]];
  var SEGN = ['torso', 'thigh', 'shin', 'foot', 'upper_arm', 'forearm'];
  var HI = 'var(--kp-hi,#F2594B)', MU = 'var(--kp-muted,#8a9a96)', AMB = '#BA7517';
  var SKIN = 'var(--kp-skin,#E3B08F)', SHIRT = 'var(--kp-shirt,#DDE5EC)', PANTS = 'var(--kp-pants,#3C4A63)', SHOE = 'var(--kp-shoe,#F6F8F9)', HAIR = 'var(--kp-hair,#3A2C2A)', EDGE = 'var(--kp-edge,rgba(28,38,52,.32))', INK = 'var(--kp-ink,#2A2F3A)';
  var CSS = '<style>.kp-h .kp-skin{stroke:' + SKIN + ';stroke-width:8;opacity:.6}.kp-h .kp-pants{stroke:' + PANTS + ';stroke-width:12;opacity:.5}.kp-h .kp-shirt{stroke:' + SHIRT + ';stroke-width:14}.kp-h .kp-solid{opacity:1}</style>';

  function ease(x) { return x < 0.5 ? 2 * x * x : 1 - Math.pow(-2 * x + 2, 2) / 2; }

  function poseAt(ex, c) {
    var f = ex.animation.frames, i = 0, j;
    while (i < f.length - 2 && c >= f[i + 1].t) i++;
    var a = f[i], b = f[i + 1];
    var p = Math.min(1, Math.max(0, (c - a.t) / (b.t - a.t))), q = ease(p), v = [];
    for (j = 0; j < a.pose.length; j++) v.push(a.pose[j] + (b.pose[j] - a.pose[j]) * q);
    for (j = v.length; j < 24; j++) v.push(0);
    return v;
  }

  function cueAt(ex, c) {
    var cs = ex.cues, m = cs[0].text;
    for (var i = 0; i < cs.length; i++) if (c >= cs[i].at) m = cs[i].text;
    return m;
  }

  function ln(cls, stroke, w, extra) {
    return '<line class="' + cls + '" stroke="' + stroke + '" stroke-width="' + w + '" stroke-linecap="round"' + (extra || '') + '/>';
  }

  function extras(fx) {
    return (fx.band || fx.strap ? '<line class="kp-s6" stroke="' + AMB + '" stroke-width="2" stroke-dasharray="4 3"/>' : '') +
      (fx.x >= 1 ? '<line class="kp-s7" stroke="' + (fx.sc || HI) + '" stroke-width="' + (fx.sw || 8) + '" stroke-linecap="' + (fx.box ? 'butt' : 'round') + '"/>' : '') +
      (fx.x >= 2 ? '<line class="kp-s8" stroke="' + (fx.sc8 || HI) + '" stroke-width="' + (fx.sw8 || 6) + '" stroke-linecap="round"/>' : '');
  }

  function stickMarkup(ex) {
    var a = ex.animation, fx = a.flags || {}, hl = a.highlight_segments || [], s = '', i, SS = supSvg(a.supports);
    for (i = 0; i < 6; i++) s += ln('kp-s' + i, hl.indexOf(SEGN[i]) > -1 ? HI : MU, i === 0 ? 12 : 8);
    return '<svg class="kp-svg" viewBox="' + a.viewBox + '" width="100%" role="img" aria-label="' + ex.name + ' animation">' +
      '<g transform="translate(0,10)"><g class="kp-st">' + a.static_svg + '</g>' + SS.u + (fx.behind ? extras(fx) : '') + s + SS.o + (fx.behind ? '' : extras(fx)) +
      (fx.nohead ? '' : '<circle class="kp-hd" r="9" fill="var(--kp-bg,transparent)" stroke="' + MU + '" stroke-width="3"/>') + SS.b +
      '</g></svg>';
  }

  function r1(n) { return Math.round(n * 10) / 10; }
  function cap(ax, ay, bx, by, ra, rb) {
    var dx = bx - ax, dy = by - ay, d = Math.sqrt(dx * dx + dy * dy), r, cx, cy;
    if (d < 0.6 || d <= Math.abs(ra - rb)) {
      if (ra >= rb) { r = ra; cx = ax; cy = ay; } else { r = rb; cx = bx; cy = by; }
      return 'M' + r1(cx - r) + ' ' + r1(cy) + 'A' + r + ' ' + r + ' 0 1 0 ' + r1(cx + r) + ' ' + r1(cy) + 'A' + r + ' ' + r + ' 0 1 0 ' + r1(cx - r) + ' ' + r1(cy) + 'Z';
    }
    var ux = dx / d, uy = dy / d, nx = -uy, ny = ux, c = (ra - rb) / d, s = Math.sqrt(1 - c * c);
    var v1x = ux * c + nx * s, v1y = uy * c + ny * s, v2x = ux * c - nx * s, v2y = uy * c - ny * s;
    return 'M' + r1(ax + ra * v1x) + ' ' + r1(ay + ra * v1y) + 'L' + r1(bx + rb * v1x) + ' ' + r1(by + rb * v1y) +
      'A' + rb + ' ' + rb + ' 0 ' + (c < 0 ? 1 : 0) + ' 0 ' + r1(bx + rb * v2x) + ' ' + r1(by + rb * v2y) +
      'L' + r1(ax + ra * v2x) + ' ' + r1(ay + ra * v2y) +
      'A' + ra + ' ' + ra + ' 0 ' + (c > 0 ? 1 : 0) + ' 0 ' + r1(ax + ra * v1x) + ' ' + r1(ay + ra * v1y) + 'Z';
  }
  function bp(cls, fill) { return '<path class="' + cls + '" fill="' + fill + '" stroke="' + EDGE + '" stroke-width=".8" stroke-linejoin="round"/>'; }
  function bc(cls, fill, r) { return '<circle class="' + cls + '" r="' + r + '" fill="' + fill + '" stroke="' + EDGE + '" stroke-width=".8"/>'; }
  function ov(cls) { return '<path class="' + cls + '" fill="' + HI + '" opacity=".8"/>'; }

  var PR = {
    th: { st: [0, 0.22, 0.55, 1], a: [8.8, 9.8, 8.2, 6.4] },
    shA: { st: [0, 0.3, 0.68, 1], a: [6.0, 6.2, 4.7, 3.8], p: [6.0, 7.5, 5.4, 3.9] },
    sh: { st: [0, 0.3, 0.68, 1], a: [6.2, 6.8, 5.0, 3.9] },
    ft: { st: [0, 0.5, 1], a: [4.6, 4.2, 3.0] },
    ua: { st: [0, 0.35, 1], a: [4.9, 5.5, 4.2] },
    fa: { st: [0, 0.3, 1], a: [4.4, 4.6, 3.0] },
    tS: [0, 0.2, 0.5, 0.76, 1], tF: [6.4, 9.6, 7.2, 8.0, 9.0], tB: [6.8, 8.0, 6.8, 7.8, 10.2],
    q0: { st: [0, 0.5, 1], f: [6.8, 9.4, 8.2], b: [6.8, 8.0, 7.8] },
    q1: { st: [0, 0.5, 1], f: [8.2, 7.4, 8.6], b: [7.8, 7.2, 9.8] }
  };
  var VENT = { up: [0, -1], down: [0, 1], right: [1, 0], left: [-1, 0] };
  function pf(q) { return r1(q[0]) + ' ' + r1(q[1]); }
  function chain(P) {
    var n = P.length - 1, s = '', i;
    for (i = 0; i < n; i++) {
      var p0 = P[Math.max(i - 1, 0)], p1 = P[i], p2 = P[i + 1], p3 = P[Math.min(i + 2, n)];
      s += 'C' + pf([p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6]) + ' ' + pf([p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6]) + ' ' + pf(p2);
    }
    return s;
  }
  function curved(A, B, st, rp, rm, shrink) {
    var dx = B[0] - A[0], dy = B[1] - A[1], d = Math.sqrt(dx * dx + dy * dy), sh = shrink || 0, i;
    if (d < 3) return cap(A[0], A[1], B[0], B[1], Math.max(1.2, rp[0] - sh), Math.max(1.2, rp[rp.length - 1] - sh));
    var nx = -dy / d, ny = dx / d, L = [], R = [];
    for (i = 0; i < st.length; i++) {
      var cx = A[0] + dx * st[i], cy = A[1] + dy * st[i], a = Math.max(1.2, rp[i] - sh), b = Math.max(1.2, rm[i] - sh);
      L.push([cx + nx * a, cy + ny * a]); R.push([cx - nx * b, cy - ny * b]);
    }
    var n = st.length - 1, hB = Math.hypot(L[n][0] - R[n][0], L[n][1] - R[n][1]) / 2, h0 = Math.hypot(L[0][0] - R[0][0], L[0][1] - R[0][1]) / 2;
    return 'M' + pf(L[0]) + chain(L) + 'A' + r1(hB) + ' ' + r1(hB) + ' 0 0 0 ' + pf(R[n]) + chain(R.slice().reverse()) + 'A' + r1(h0) + ' ' + r1(h0) + ' 0 0 0 ' + pf(L[0]) + 'Z';
  }
  function fillFor(m, pp, qq, u) { return 'url(#' + m + (Math.abs(qq[0] - pp[0]) >= Math.abs(qq[1] - pp[1]) ? 'V' : 'H') + u + ')'; }
  function segC(el, cls, P, Q, st, rp, rm, shrink, m, u) {
    var len = Math.abs(P[0] - Q[0]) + Math.abs(P[1] - Q[1]);
    if (len < 1.5) { set(el, cls, { display: 'none' }); return; }
    var o = { d: curved(P, Q, st, rp, rm || rp, shrink), display: 'inline' };
    if (m) o.fill = fillFor(m, P, Q, u);
    set(el, cls, o);
  }
  function headPos(N, H, fx) {
    var b = fx.front ? [190, 46] : N, dx = H[0] - b[0], dy = H[1] - b[1], l = Math.sqrt(dx * dx + dy * dy);
    if (l < 1) return [H[0], H[1] - 22];
    return [b[0] + dx / l * 22, b[1] + dy / l * 22];
  }
  function sideOf(P, Q, V) { var dx = Q[0] - P[0], dy = Q[1] - P[1], d = Math.sqrt(dx * dx + dy * dy) || 1; return (-dy / d) * V[0] + (dx / d) * V[1] >= 0; }

  var UID = 0;
  function defsFor(u) {
    function g(id, hi, mid, lo, h) { return '<linearGradient id="' + id + u + '" x1="0" y1="0" x2="' + (h ? 1 : 0) + '" y2="' + (h ? 0 : 1) + '"><stop offset="0" stop-color="' + hi + '"/><stop offset=".5" stop-color="' + mid + '"/><stop offset="1" stop-color="' + lo + '"/></linearGradient>'; }
    var M = [['sk', 'var(--kp-skin-hi,#F4D0B5)', SKIN, 'var(--kp-skin-lo,#C48A68)'], ['sh', 'var(--kp-shirt-hi,#F9FBFD)', SHIRT, 'var(--kp-shirt-lo,#B4C1CF)'], ['pa', 'var(--kp-pants-hi,#5E6F8D)', PANTS, 'var(--kp-pants-lo,#222C42)'], ['so', 'var(--kp-shoe-hi,#FFFFFF)', SHOE, 'var(--kp-shoe-lo,#C4CDD3)']];
    var s = '';
    M.forEach(function (m) { s += g(m[0] + 'V', m[1], m[2], m[3], false) + g(m[0] + 'H', m[1], m[2], m[3], true); });
    s += '<radialGradient id="hd' + u + '" cx=".35" cy=".3" r=".85"><stop offset="0" stop-color="var(--kp-skin-hi,#F4D0B5)"/><stop offset=".6" stop-color="' + SKIN + '"/><stop offset="1" stop-color="var(--kp-skin-lo,#C48A68)"/></radialGradient>';
    s += '<filter id="bl' + u + '" x="-40%" y="-40%" width="180%" height="180%"><feGaussianBlur stdDeviation="2.6"/></filter>';
    return '<defs>' + s + '</defs>';
  }
  function ghostPath(v, fx) {
    var P = function (i) { return [v[i * 2 - 2], v[i * 2 - 1]]; }, N = P(2), Pp = P(3), K = P(4), A = P(5), T = P(6), E = P(7), W = P(8), H = P(1), d = '';
    var add = function (x, y, ra, rb) { if (Math.abs(x[0] - y[0]) + Math.abs(x[1] - y[1]) > 1.5) d += cap(x[0], x[1], y[0], y[1], ra, rb); };
    if (fx.nohead) { add(N, Pp, 6, 5); add(Pp, K, 5, 4.6); add(K, A, 4, 3.2); add(A, T, 3.2, 2.4); return d; }
    add(N, Pp, 8.2, 9);
    if (fx.quad) { add(Pp, K, 8.5, 9.2); add(K, A, 8.5, 6.4); add(A, T, 6, 3.8); } else { add(Pp, K, 8.6, 6.2); add(K, A, 6, 4); add(A, T, 4.5, 3.2); }
    add(N, E, 5, 4.2); add(E, W, 4, 3.2);
    if (fx.mirror) { var m = function (q) { return [2 * fx.mirror - q[0], q[1]]; }; add(m(N), m(E), 5, 4.2); add(m(E), m(W), 4, 3.2); }
    var Hs = headPos(N, H, fx);
    return d + cap(Hs[0], Hs[1], Hs[0], Hs[1], 10, 10);
  }
  function arrowSvg(ar) {
    var f = ar.from, c = ar.ctl, t = ar.to, dx = t[0] - c[0], dy = t[1] - c[1], l = Math.sqrt(dx * dx + dy * dy) || 1, ux = dx / l, uy = dy / l;
    var bx = t[0] - ux * 6.5, by = t[1] - uy * 6.5, px = -uy * 3.4, py = ux * 3.4;
    return '<path d="M' + f[0] + ' ' + f[1] + 'Q' + c[0] + ' ' + c[1] + ' ' + r1(bx) + ' ' + r1(by) + '" fill="none" stroke="var(--kp-arrow,#4F6F8F)" stroke-width="1.7" stroke-dasharray="3.5 2.6" stroke-linecap="round" opacity=".85"/>' +
      '<path d="M' + t[0] + ' ' + t[1] + 'L' + r1(bx + px) + ' ' + r1(by + py) + 'L' + r1(bx - px) + ' ' + r1(by - py) + 'Z" fill="var(--kp-arrow,#4F6F8F)" opacity=".9"/>';
  }
  function frontBody(F) {
    var shirt = '<path fill="' + F('sh') + '" stroke="' + EDGE + '" stroke-width=".8" stroke-linejoin="round" d="M170 48C175 40 205 40 210 48C210 56 209 61 207 67C205 75 203 80 204 87C205 93 208 98 209 104L171 104C172 98 175 93 176 87C177 80 175 75 173 67C171 61 170 56 170 48Z"/>';
    var leg = function (x0, x1) { return '<path fill="' + F('pa') + '" stroke="' + EDGE + '" stroke-width=".8" d="' + curved([x0, 102], [x1, 147], [0, 0.3, 0.62, 1], [9.8, 9.2, 6.6, 4.6], [9.8, 9.2, 6.6, 4.6]) + '"/>'; };
    var shoes = '<ellipse cx="174" cy="149.5" rx="8" ry="3.4" fill="' + F('so') + '" stroke="' + EDGE + '" stroke-width=".8"/><ellipse cx="206" cy="149.5" rx="8" ry="3.4" fill="' + F('so') + '" stroke="' + EDGE + '" stroke-width=".8"/>';
    var neck = '<path fill="' + F('sk') + '" stroke="' + EDGE + '" stroke-width=".8" d="' + cap(190, 36, 190, 47, 4.2, 4.8) + '"/>';
    return leg(181, 177) + leg(199, 203) + shoes + shirt;
  }

  function humanMarkup(ex) {
    var u = ++UID, a = ex.animation, fx = a.flags || {}, hl = a.highlight_segments || [], s = '', o = '', i, stat = a.static_svg;
    var H = function (n) { return hl.indexOf(n) > -1; };
    var F = function (m) { return 'url(#' + m + 'V' + u + ')'; };
    var vb = a.viewBox.split(' ').map(Number);
    if (fx.nohead) {
      s = bp('kp-tbA', F('sk')) + bp('kp-tbB', F('sk')) + bc('kp-hl', F('sk'), 6.5) + bp('kp-f0', F('sk')) + bp('kp-f1', F('sk')) + bp('kp-f2', F('sk')) + bp('kp-f3', F('sk')) + '<circle class="kp-nl" r="1.2" fill="#fff" opacity=".85"/>';
      for (i = 0; i < 4; i++) if (H(SEGN[i])) o += ov('kp-o' + i);
    } else {
      if (fx.front) stat = stat.replace(/<line[^>]*kp-solid[^>]*\/>/g, '') + frontBody(F);
      if (fx.quad) s = bp('kp-s3', F('pa')) + bp('kp-s2', F('pa')) + bc('kp-pv', F('pa'), 8.8) + bc('kp-gl', F('pa'), 6) + bp('kp-s1', F('sh')) + bp('kp-s0', F('sh'));
      else s = bp('kp-s3', F('so')) + bp('kp-s2', F('pa')) + bp('kp-s1', F('pa')) + bc('kp-pv', F('pa'), 8.6) + bc('kp-gl', F('pa'), 6) + bp('kp-s0', F('sh')) + bc('kp-bt', F('sh'), 5);
      s += bp('kp-nk', F('sk'));
      var arm = function (p) { return bp('kp-' + p + '4', F('sk')) + bp('kp-' + p + 'sl', F('sh')) + bc('kp-' + p + 'sd', F('sh'), 6.2) + bp('kp-' + p + '5', F('sk')) + bc('kp-' + p + 'hn', F('sk'), 4.4); };
      s += arm('');
      if (fx.mirror) s += arm('m');
      s += '<circle class="kp-hd" r="10" fill="url(#hd' + u + ')" stroke="' + EDGE + '" stroke-width=".8"/>' + bp('kp-hr', HAIR) + bc('kp-er', F('sk'), 2.3);
      if (fx.quad) { for (i = 0; i < 4; i++) if (H(SEGN[i])) o += ov('kp-o' + i); }
      else {
        if (H('torso')) o += ov('kp-o0');
        for (i = 1; i < 4; i++) if (H(SEGN[i])) o += ov('kp-o' + i);
      }
      for (i = 4; i < 6; i++) if (H(SEGN[i])) o += ov('kp-o' + i) + (fx.mirror ? ov('kp-q' + i) : '');
    }
    var mat = '';
    if (fx.mat3d && a.floor != null) mat = '<rect x="' + (vb[0] + 6) + '" y="' + (a.floor - 38) + '" width="' + r1(vb[2] - 12) + '" height="38" rx="5" fill="var(--kp-mat,#9DBBD0)" opacity=".9"/><rect x="' + (vb[0] + 10) + '" y="' + (a.floor - 36) + '" width="' + r1(vb[2] - 20) + '" height="3" rx="1.5" fill="rgba(255,255,255,.35)"/>';
    else if (fx.mat && a.floor != null) mat = '<rect x="' + (vb[0] + 8) + '" y="' + (a.floor - 3.5) + '" width="' + r1(vb[2] - 16) + '" height="5" rx="2.5" fill="var(--kp-mat,#9DBBD0)"/>';
    var ghost = (a.arrow && a.peak > 0) ? '<path d="' + ghostPath(a.frames[a.peak].pose.concat([0, 0, 0, 0, 0, 0, 0, 0]), fx) + '" fill="var(--kp-ghost,rgba(90,120,150,.16))"/>' : '';
    var gs = a.floor != null ? '<ellipse class="kp-gs" fill="rgba(0,0,0,.11)" ry="2.8"/>' : '';
    var SUP = supSvg(a.supports);
    var ovl = o ? '<use href="#ov' + u + '" filter="url(#bl' + u + ')" opacity=".55"/><g id="ov' + u + '">' + o + '</g>' : '';
    return '<svg class="kp-svg kp-h" data-uid="' + u + '" viewBox="' + a.viewBox + '" width="100%" role="img" aria-label="' + ex.name + ' animation">' + CSS + defsFor(u) +
      '<g transform="translate(0,10)"><g class="kp-st">' + stat + '</g>' + mat + SUP.u + ghost + gs + (fx.behind ? extras(fx) : '') + s + ovl + SUP.o + (fx.behind ? '' : extras(fx)) + (a.arrow ? arrowSvg(a.arrow) : '') + SUP.b + '</g></svg>';
  }

  function supSvg(list) {
    var u = '', o = '', bd = '';
    (list || []).forEach(function (s) {
      var x = s.x, y = s.y, w = s.w, h = s.h, g = '';
      if (s.t === 'pillow') g = '<rect x="' + x + '" y="' + y + '" width="' + w + '" height="' + h + '" rx="' + Math.min(h / 2, 7) + '" fill="var(--kp-pillow,#F6F3EE)" stroke="' + EDGE + '" stroke-width=".8"/><path d="M' + (x + 6) + ' ' + r1(y + h / 2) + 'H' + (x + w - 6) + '" stroke="rgba(0,0,0,.14)" stroke-width=".7" stroke-dasharray="2 2" fill="none"/>';
      else if (s.t === 'towel') { var cx = x + w / 2, cy = y + h / 2, r = w / 2; g = '<circle cx="' + cx + '" cy="' + cy + '" r="' + r + '" fill="var(--kp-towel,#EBCB9F)" stroke="' + EDGE + '" stroke-width=".8"/><path d="M' + r1(cx) + ' ' + r1(cy - r * 0.55) + 'A' + r1(r * 0.55) + ' ' + r1(r * 0.55) + ' 0 1 1 ' + r1(cx - r * 0.3) + ' ' + r1(cy + r * 0.45) + '" fill="none" stroke="rgba(0,0,0,.3)" stroke-width=".7"/>'; }
      else if (s.t === 'bolster') g = '<rect x="' + x + '" y="' + y + '" width="' + w + '" height="' + h + '" rx="' + h / 2 + '" fill="var(--kp-bolster,#B8CCDD)" stroke="' + EDGE + '" stroke-width=".8"/><path d="M' + (x + 5) + ' ' + r1(y + h * 0.32) + 'H' + (x + w - 5) + '" stroke="rgba(255,255,255,.6)" stroke-width="1" stroke-linecap="round" fill="none"/>';
